static boolean canJump(int[] nums) {
  int reach = 0;
  for (int i = 0; i < nums.length; i++) {
    if (i > reach) return false;
    reach = Math.max(reach, i + nums[i]);
  }
  return true;
}

static List<List<Integer>> subsets(int[] nums) {
  List<List<Integer>> res = new ArrayList<>();
  go(nums, 0, new ArrayList<>(), res);
  return res;
}
static void go(int[] nums, int start, List<Integer> cur, List<List<Integer>> res) {
  res.add(new ArrayList<>(cur));
  for (int i = start; i < nums.length; i++) {
    cur.add(nums[i]); go(nums, i + 1, cur, res); cur.remove(cur.size() - 1);
  }
}

def combination_sum(cands, target):
    cands = sorted(cands)
    res = []
    def go(start, remaining, cur):
        if remaining == 0:
            res.append(cur[:]); return
        for i in range(start, len(cands)):
            if cands[i] > remaining: break
            cur.append(cands[i]); go(i, remaining - cands[i], cur); cur.pop()
    go(0, target, [])
    return res
